// Independent ground truth for body facts, from the TypeScript compiler API (binder symbols, no resolution).
// Usage: node truth.cjs facts-<name>.jsonl...  Prints counts and soundness violations.
const fs = require('fs');
const ts = require('/Users/gabe/Projects/caliper-fixtures/oracle-local/apps/oracle/node_modules/typescript');

const records = process.argv.slice(2).flatMap((file) =>
  fs.readFileSync(file, 'utf8').split('\n').filter(Boolean).map((line) => ({ ...JSON.parse(line), set: file })),
);

// Byte offset (UTF-8) to UTF-16 index, per file.
const offsets = new Map();
function toUtf16(file, byte) {
  let map = offsets.get(file);
  if (!map) {
    const text = fs.readFileSync(file, 'utf8');
    map = new Map();
    let b = 0;
    for (let i = 0; i < text.length; ) {
      map.set(b, i);
      const cp = text.codePointAt(i);
      b += cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4;
      i += cp >= 0x10000 ? 2 : 1;
    }
    map.set(b, text.length);
    offsets.set(file, map);
  }
  return map.get(byte);
}

const WRAPPERS = new Set([
  ts.SyntaxKind.ParenthesizedExpression,
  ts.SyntaxKind.AsExpression,
  ts.SyntaxKind.NonNullExpression,
  ts.SyntaxKind.SatisfiesExpression,
  ts.SyntaxKind.TypeAssertionExpression,
]);
function up(node) {
  let cur = node;
  while (cur.parent && WRAPPERS.has(cur.parent.kind)) cur = cur.parent;
  return cur;
}
const ASSIGN = new Set([
  ts.SyntaxKind.EqualsToken, ts.SyntaxKind.PlusEqualsToken, ts.SyntaxKind.MinusEqualsToken,
  ts.SyntaxKind.AsteriskEqualsToken, ts.SyntaxKind.SlashEqualsToken, ts.SyntaxKind.BarBarEqualsToken,
  ts.SyntaxKind.AmpersandAmpersandEqualsToken, ts.SyntaxKind.QuestionQuestionEqualsToken,
]);
// Whether a member access is only read: not called, tagged, written, updated, deleted or a loop target.
function memberIsRead(member) {
  const m = up(member);
  const p = m.parent;
  if (!p) return true;
  if (ts.isCallExpression(p) && p.expression === m) return false;
  if (ts.isTaggedTemplateExpression(p) && p.tag === m) return false;
  if (ts.isBinaryExpression(p) && ASSIGN.has(p.operatorToken.kind) && p.left === m) return false;
  if (ts.isPrefixUnaryExpression(p) || ts.isPostfixUnaryExpression(p)) {
    if (p.operator === ts.SyntaxKind.PlusPlusToken || p.operator === ts.SyntaxKind.MinusMinusToken) return false;
  }
  if (ts.isDeleteExpression(p)) return false;
  if ((ts.isForInStatement(p) || ts.isForOfStatement(p)) && p.initializer === m) return false;
  if (ts.isArrayLiteralExpression(p) || ts.isPropertyAssignment(p) || ts.isShorthandPropertyAssignment(p) ||
      ts.isSpreadElement(p)) {
    // A member inside a literal is fine unless the literal is a destructuring target.
    let lit = p;
    while (lit && !ts.isBinaryExpression(lit) && !ts.isStatement(lit)) lit = lit.parent;
    if (lit && ts.isBinaryExpression(lit) && lit.operatorToken.kind === ts.SyntaxKind.EqualsToken &&
        lit.left.pos <= m.pos && m.end <= lit.left.end) return false;
  }
  return true;
}

function truthOf(checker, fn, sf) {
  const truth = { reads: new Set(), handoff: false, why: [] };
  const tracked = new Map(); // symbol -> 'props' | 'rest'
  const queue = [];
  const track = (nameNode, kind) => {
    const sym = checker.getSymbolAtLocation(nameNode);
    if (sym && !tracked.has(sym)) { tracked.set(sym, kind); queue.push(sym); }
  };
  const destructure = (pattern) => {
    for (const el of pattern.elements) {
      if (el.dotDotDotToken) {
        if (ts.isIdentifier(el.name)) track(el.name, 'rest'); else { truth.handoff = true; truth.why.push('rest pattern'); }
        continue;
      }
      const key = el.propertyName ?? el.name;
      if (ts.isIdentifier(key) || ts.isStringLiteral(key) || ts.isNumericLiteral(key) || ts.isPrivateIdentifier(key)) {
        truth.reads.add(key.text);
      } else if (ts.isComputedPropertyName(key) && ts.isStringLiteralLike(key.expression)) {
        truth.reads.add(key.expression.text);
      } else { truth.handoff = true; truth.why.push('computed key'); }
    }
  };
  const param = fn.parameters[0];
  if (!param) return null;
  if (ts.isIdentifier(param.name)) track(param.name, 'props');
  else if (ts.isObjectBindingPattern(param.name)) destructure(param.name);
  else { truth.handoff = true; truth.why.push('array param'); }

  while (queue.length) {
    const sym = queue.shift();
    const kind = tracked.get(sym);
    const visit = (node) => {
      if (ts.isIdentifier(node) && node.parent) {
        const p0 = node.parent;
        let isRef;
        if (ts.isShorthandPropertyAssignment(p0) && p0.name === node) {
          isRef = checker.getShorthandAssignmentValueSymbol(p0) === sym;
        } else {
          const decl = (ts.isBindingElement(p0) || ts.isParameter(p0) || ts.isVariableDeclaration(p0)) && p0.name === node;
          isRef = !decl && checker.getSymbolAtLocation(node) === sym;
        }
        if (isRef) classify(node, kind);
      }
      ts.forEachChild(node, visit);
    };
    visit(fn);
  }
  return truth;

  function classify(id, kind) {
    const cur = up(id);
    const p = cur.parent;
    const hand = (why) => { truth.handoff = true; truth.why.push(`${why} @${sf.getLineAndCharacterOfPosition(id.getStart(sf)).line + 1}`); };
    if (ts.isPropertyAccessExpression(p) && p.expression === cur) {
      if (memberIsRead(p)) truth.reads.add(p.name.text); else hand('member write/call');
    } else if (ts.isElementAccessExpression(p) && p.expression === cur) {
      if (ts.isStringLiteralLike(p.argumentExpression) && memberIsRead(p)) truth.reads.add(p.argumentExpression.text);
      else hand('element access');
    } else if (ts.isVariableDeclaration(p) && p.initializer === cur && ts.isObjectBindingPattern(p.name)) {
      destructure(p.name);
    } else if (ts.isBinaryExpression(p) && p.operatorToken.kind === ts.SyntaxKind.EqualsToken && p.right === cur &&
               ts.isObjectLiteralExpression(p.left)) {
      for (const prop of p.left.properties) {
        if ((ts.isPropertyAssignment(prop) || ts.isShorthandPropertyAssignment(prop)) && ts.isIdentifier(prop.name)) {
          truth.reads.add(prop.name.text);
        } else hand('assignment pattern');
      }
    } else if (ts.isJsxSpreadAttribute(p)) {
      if (kind === 'props') hand('jsx spread of props');
    } else {
      hand(ts.SyntaxKind[p.kind]);
    }
  }
}

const byFile = new Map();
for (const r of records) (byFile.get(r.file) ?? byFile.set(r.file, []).get(r.file)).push(r);
const files = [...byFile.keys()];
let checked = 0, handedOn = 0, unmatched = 0, noParam = 0, extraReads = 0;
const violations = [];
const BATCH = 400;
for (let i = 0; i < files.length; i += BATCH) {
  const batch = files.slice(i, i + BATCH);
  const program = ts.createProgram(batch, {
    noResolve: true, noLib: true, allowJs: true, jsx: ts.JsxEmit.Preserve, types: [], skipLibCheck: true,
  });
  const checker = program.getTypeChecker();
  for (const file of batch) {
    const sf = program.getSourceFile(file);
    for (const r of byFile.get(file)) {
      const start = toUtf16(file, r.fn[0]), end = toUtf16(file, r.fn[1]);
      let fn = null;
      const find = (node) => {
        if (fn) return;
        if ((ts.isFunctionDeclaration(node) || ts.isFunctionExpression(node) || ts.isArrowFunction(node)) &&
            node.end === end &&
            // oxc starts a function at `function`/`async`, TypeScript at its first modifier (`export`, `default`).
            (node.getStart(sf) === start ||
             (node.modifiers && ts.skipTrivia(sf.text, node.modifiers.end) === start) ||
             (node.modifiers && node.modifiers.some((m) => m.getStart(sf) === start)))) { fn = node; return; }
        ts.forEachChild(node, find);
      };
      find(sf);
      if (!fn) { unmatched++; continue; }
      const truth = truthOf(checker, fn, sf);
      if (!truth) { noParam++; continue; }
      checked++;
      if (r.handed_on) { handedOn++; continue; }
      const missed = [...truth.reads].filter((key) => !r.reads.includes(key));
      const extra = r.reads.filter((key) => !truth.reads.has(key));
      if (extra.length) extraReads++;
      if (truth.handoff || missed.length) {
        violations.push({ set: r.set, file, name: r.name, missed, handoff: truth.why, ours: r.reads });
      }
    }
  }
}
console.log(JSON.stringify({ records: records.length, checked, handedOn, notHandedOn: checked - handedOn, unmatched,
  noParam, withExtraReads: extraReads, violations: violations.length }));
for (const v of violations.slice(0, 15)) console.log(JSON.stringify(v));

